// ── Killer Instinct Gold game identity (recon: ROM header + XXH3) ───────────────────────
// SHA1: ba52e91b44450c548467044b26951353dc491e04 · internal name "Killer Instinct Gold"
static constexpr uint64_t KIGOLD_ROM_HASH        = 0x590175ABD880D2C9ULL;
static constexpr uint32_t KIGOLD_ENTRYPOINT_VRAM = 0x80000400;

extern "C" void recomp_entrypoint(uint8_t* rdram, recomp_context* ctx);

// AHEAD-OF-TIME DECOMPRESSION: registers the statically-recompiled functions of KI Gold's
// runtime-decompressed main program (vram 0x8000F960) into the engine func map, so the
// `jalr 0x8000F960` boot dispatch resolves to native code instead of the MIPS interpreter.
namespace recomp { void register_kigold_decomp_overlay(); }
// AHEAD-OF-TIME DECOMPRESSION (2nd level): KI Gold's f960 main program dispatches into a
// SECOND runtime-installed overlay at vram 0x801ABB20; register its 283 statically-recompiled
// functions too, so post-graphics-init code runs native instead of in the MIPS interpreter.
namespace recomp { void register_kigold_overlay_801a(); }

