static void prompt_for_rom(const char* rom_hint) {
    std::filesystem::path rom_path;

#if defined(_WIN32)
    if (rom_hint && *rom_hint) {
        rom_path = rom_hint;
    } else {
        OPENFILENAMEA ofn   = {};
        char          path[MAX_PATH] = {};
        ofn.lStructSize = sizeof(ofn);
        ofn.lpstrFilter = "N64 ROM Files\0*.z64;*.n64;*.v64\0All Files\0*.*\0";
        ofn.lpstrFile   = path;
        ofn.nMaxFile    = MAX_PATH;
        ofn.lpstrTitle  = "Select Killer Instinct Gold ROM";
        ofn.Flags       = OFN_FILEMUSTEXIST | OFN_PATHMUSTEXIST;
        if (!GetOpenFileNameA(&ofn)) {
            kigold_show_error("ROM Required",
                "A Killer Instinct Gold ROM is required.\n"
                "Please supply your own legally obtained copy.");
            std::exit(0);
        }
        rom_path = path;
    }
#else
    // No native file dialog wired off Windows: take the ROM path from argv[1] or the
    // KIGOLD_ROM env var (e.g. an SBC/console that already has the ROM at a known path).
    if (!rom_hint || !*rom_hint) rom_hint = std::getenv("KIGOLD_ROM");
    if (!rom_hint || !*rom_hint) {
        kigold_show_error("ROM Required",
            "Pass the Killer Instinct Gold ROM path as the first argument,\n"
            "or set the KIGOLD_ROM environment variable.");
        std::exit(0);
    }
    rom_path = rom_hint;
#endif

    std::u8string out_id = u8"kigold_us";
    auto err = recomp::select_rom(rom_path, out_id);
    switch (err) {
    case recomp::RomValidationError::Good:
        return;
    case recomp::RomValidationError::IncorrectRom:
    case recomp::RomValidationError::IncorrectVersion:
        kigold_show_error("Wrong ROM",
            "The selected ROM does not match Killer Instinct Gold.\n"
            "Expected SHA1: ba52e91b44450c548467044b26951353dc491e04");
        std::exit(1);
    case recomp::RomValidationError::NotARom:
        kigold_show_error("Not an N64 ROM", "The selected file does not appear to be an N64 ROM.");
        std::exit(1);
    default:
        kigold_show_error("ROM Error", "Failed to read the selected ROM file.");
        std::exit(1);
    }
}

static int kigold_app_main(int argc, char** argv)
{
    const char* rom_hint = (argc > 1) ? argv[1] : nullptr;

#if defined(_WIN32)
    SetUnhandledExceptionFilter(kigold_unhandled_exception);
#endif
    SDL_SetMainReady();

#if defined(_WIN32)
    const char* appdata = std::getenv("APPDATA");
    if (!appdata) appdata = ".";
    std::filesystem::path config_path = std::filesystem::path(appdata) / "kigoldpc";
#else
    const char* xdg  = std::getenv("XDG_CONFIG_HOME");
    const char* home = std::getenv("HOME");
    std::filesystem::path config_base =
        (xdg && *xdg) ? std::filesystem::path(xdg)
                      : (home ? std::filesystem::path(home) / ".config"
                              : std::filesystem::path("."));
    std::filesystem::path config_path = config_base / "kigoldpc";
#endif
    std::filesystem::create_directories(config_path);

    {
        std::filesystem::path log_path = config_path / "kigoldpc_diag.log";
        FILE* f = nullptr;
#if defined(_WIN32)
        freopen_s(&f, log_path.string().c_str(), "w", stderr);
#else
        f = freopen(log_path.string().c_str(), "w", stderr);
#endif
        if (f) { setvbuf(f, nullptr, _IONBF, 0); fprintf(stderr, "[kigoldpc] diagnostic log started\n"); }
        std::filesystem::path stdout_path = config_path / "kigoldpc_stdout.log";
        FILE* fout = nullptr;
#if defined(_WIN32)
        freopen_s(&fout, stdout_path.string().c_str(), "w", stdout);
#else
        fout = freopen(stdout_path.string().c_str(), "w", stdout);
#endif
        if (fout) { setvbuf(fout, nullptr, _IONBF, 0); fprintf(stdout, "[kigoldpc] stdout log started\n"); }
    }

    recomp::register_config_path(config_path);

    recomp::GameEntry entry{};
    entry.rom_hash           = KIGOLD_ROM_HASH;
    entry.internal_name      = "Killer Instinct Gold";
    entry.game_id            = u8"kigold_us";
    entry.mod_game_id        = "";
    entry.save_type          = recomp::SaveType::Eep4k;
    entry.is_enabled         = true;
    entry.entrypoint_address = KIGOLD_ENTRYPOINT_VRAM;
    entry.entrypoint         = recomp_entrypoint;
    recomp::register_game(entry);

    recomp::overlays::register_overlays(
        recomp::overlays::overlay_section_table_data_t{
            .code_sections      = section_table,
            .num_code_sections  = sizeof(section_table) / sizeof(section_table[0]),
            .total_num_sections = num_sections,
        },
        recomp::overlays::overlays_by_index_t{
            .table = overlay_sections_by_index,
            .len   = sizeof(overlay_sections_by_index) / sizeof(overlay_sections_by_index[0]),
        });

    // AHEAD-OF-TIME DECOMPRESSION: pin the statically-recompiled decompressed-overlay
    // functions (vram 0x8000F960, 538 funcs). Pinned funcs survive init_overlays()'s
    // func_map.clear() and are checked by get_function() before the interpreter fallback,
    // so `jalr 0x8000F960` now dispatches to native code.
    recomp::register_kigold_decomp_overlay();
    // 2nd-level overlay (vram 0x801ABB20, 283 funcs): the post-graphics-init code path.
    // RECOMP_NO_OVL801A=1 skips this registration so the whole 0x801ABB20 window runs in the MIPS
    // interpreter from LIVE RDRAM instead of from the captured snapshot. This is the KILL TEST for
    // the 2026-08-29 diagnosis: the game's decompressor (func_80000FA0) writes fight content over
    // this window at t~21.25s, clobbering function BODIES while their entry words survive, so the
    // pinned snapshot keeps dispatching menu code that is no longer there. If interpreting live
    // RDRAM lets the game past the wall, the diagnosis holds and a validity-checked dispatch is
    // worth building properly; if it does NOT, the diagnosis is wrong and no guard will help.
    if (std::getenv("RECOMP_NO_OVL801A") == nullptr) {
        recomp::register_kigold_overlay_801a();
    } else {
        fprintf(stderr, "[ovl801a] registration SKIPPED (RECOMP_NO_OVL801A) - 0x801ABB20 window "
                        "will run in the interpreter from live RDRAM\n");
        fflush(stderr);
    }

    recomp::check_all_stored_roms();
    std::u8string game_id = u8"kigold_us";
    if (!recomp::is_rom_valid(game_id)) {
        prompt_for_rom(rom_hint);
        recomp::check_all_stored_roms();
        if (!recomp::is_rom_valid(game_id)) {
            kigold_show_error("Error", "ROM validation failed after selection.");
            return 1;
        }
    }

    SDL_Init(SDL_INIT_AUDIO);
    kigold_audio_init();
    kigold_input_init();

    recomp::start_game(game_id);

    recomp::Configuration cfg{};
    cfg.project_version      = { 0, 1, 0, "" };
    cfg.rsp_callbacks        = get_rsp_callbacks();
    cfg.renderer_callbacks   = { .create_render_context = kigold::renderer::create_render_context };
    cfg.audio_callbacks      = get_audio_callbacks();
    cfg.input_callbacks      = get_input_callbacks();
    cfg.gfx_callbacks        = {
        .create_gfx    = create_gfx,
        .create_window = create_window,
        .update_gfx    = update_gfx,
    };
    cfg.events_callbacks     = {
        .vi_callback       = kigold_vi_callback,
        .gfx_init_callback = kigold_gfx_init_callback,
    };
    cfg.error_handling_callbacks = { .message_box = kigold_message_box };
    cfg.threads_callbacks    = { .get_game_thread_name = kigold_get_thread_name };
    cfg.message_queue_control = {
        .requeue_timer = true,
        .requeue_sp    = true,
        .requeue_si    = true,
        .requeue_ai    = false,
        .requeue_vi    = false,
        .requeue_pi    = false,
        .requeue_dp    = true,
    };

    recomp::start(cfg);

    SDL_Quit();
    return 0;
}

